#include <cstdio>
#include <cstring>

char s[100005];
char stk[100005];

int main() {
    if (!fgets(s, sizeof(s), stdin)) { printf("YES\n"); return 0; }
    int top = 0;
    int len = (int)strlen(s);
    int ok = 1;
    for (int i = 0; i < len; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stk[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            char need = (c == ')') ? '(' : (c == ']' ? '[' : '{');
            if (top == 0 || stk[top - 1] != need) { ok = 0; break; }
            --top;
        }
    }
    if (top != 0) ok = 0;
    printf("%s\n", ok ? "YES" : "NO");
    return 0;
}
